INSERT OR IGNORE INTO questionnaire_versions (id, tool_id, version, content_hash, scoring_method, definition_json, validity_notes, published_at) VALUES ('brief@1.0', 'brief', '1.0', '29adab2501d37f0378aa7d17ce9c64b58531be6f1c3c376c63e7ca9fc99b856a', 'brief-sum-v1', '{"bands":[{"min":8,"text":"Les fondations sont posées. Vérifiez que chacun des acteurs les interprète de la même façon avant de lancer l''exécution.","title":"Un brief solide"},{"min":4,"text":"Certains éléments restent ambigus. Cette ambiguïté se paie souvent en révisions et en délais : mieux vaut la lever avant la production.","title":"Un brief à consolider"},{"min":0,"text":"Le brief ne dit pas encore quel problème l''intervention doit résoudre. Reprenez le problème, l''audience et l''objectif avant d''engager des ressources de production.","title":"Un brief à reconstruire"}],"labels":["Le problème business","L''audience","L''objectif","La direction stratégique","Les critères de réussite"],"prompts":["Le brief nomme-t-il le problème business à résoudre, et pas seulement ce qu''il faut produire ?","Précise-t-il la perception, le comportement ou la décision que l''on cherche à influencer chez une audience définie ?","Le résultat que l''intervention créative doit produire est-il formulé clairement ?","Une proposition ou une idée directrice guide-t-elle le travail ?","Les critères pour évaluer le résultat sont-ils définis avant l''exécution ?"],"scale":{"0":"Pas encore","1":"En partie","2":"Oui, clairement"}}', 'Cinq questions, score sur 10. Oriente une première réflexion, ne remplace pas un audit.', '2026-11-23T00:00:00Z');
INSERT OR IGNORE INTO questionnaire_versions (id, tool_id, version, content_hash, scoring_method, definition_json, validity_notes, published_at) VALUES ('diag@1.0', 'diag', '1.0', '385394c333bce0619a19925236c6dd209153824c9e6591e507a18b62a758b169', 'diag-max-v1', '{"ch":[{"d":"Briefs, validations, agences et équipes internes fonctionnent chacun à leur manière. Le travail sort, mais chaque projet repart de zéro et la qualité dépend de qui s''en occupe.","id":"fragmented-operations","offer":"Creative Operating System","oid":"cos","ourl":"accompagnement/creative-operating-system.html","t":"Des opérations créatives fragmentées"},{"d":"Les clients peinent à dire pourquoi vous plutôt qu''un concurrent. Les campagnes changent à chaque saison et la marque n''accumule jamais un sens qui lui soit propre.","id":"weak-differentiation","offer":"Brand Intelligence","oid":"brand","ourl":"accompagnement/brand-intelligence.html","t":"Une différenciation de marque trop faible"},{"d":"Direction, marketing et équipes créatives poursuivent des priorités différentes. Les décisions sont rouvertes tardivement et l''énergie part en arbitrages plutôt qu''en progrès.","id":"strategic-misalignment","offer":"MCPS Diagnostic","oid":"diagnostic","ourl":"accompagnement/diagnostic-mcps.html","t":"Un désalignement stratégique"},{"d":"Cycles de validation longs, rôles flous et reprises absorbent le temps qui devrait aller à la réflexion. Les équipes sont occupées ; les résultats ne progressent pas.","id":"inefficient-systems","offer":"Creative Operating System","oid":"cos","ourl":"accompagnement/creative-operating-system.html","t":"Des systèmes créatifs inefficaces"},{"d":"Les budgets augmentent, la visibilité suit, mais l''effet business reste difficile à voir. Personne ne peut dire avec certitude quel levier limite réellement la performance.","id":"underperforming-investments","offer":"MCPS Diagnostic","oid":"diagnostic","ourl":"accompagnement/diagnostic-mcps.html","t":"Des investissements marketing qui ne rendent pas"},{"d":"Les outils sont testés équipe par équipe, sans règles communes, sans standard de qualité, sans vision claire de l''endroit où l''IA crée de la valeur et de celui où elle crée du risque.","id":"ai-without-architecture","offer":"Transformation 90","oid":"t90","ourl":"accompagnement/transformation-90.html","t":"Une adoption de l''IA sans architecture stratégique"},{"d":"Nouveaux marchés, nouveaux produits, nouveaux publics arrivent plus vite que la marque, les équipes et les processus ne peuvent les absorber.","id":"growth-without-readiness","offer":"Growth Architecture","oid":"growth","ourl":"accompagnement/growth-architecture.html","t":"Une croissance sans préparation organisationnelle"}],"contact":"contact.html","q":["Chaque équipe, agence ou prestataire travaille à sa manière, et la qualité dépend de qui s''occupe du projet.","Si l''on retirait votre logo de vos campagnes, on pourrait les attribuer à un concurrent.","Direction, marketing et équipes créatives ne poursuivent pas exactement les mêmes priorités.","Les projets créatifs prennent trop de temps : retouches, validations tardives, briefs incomplets.","Vous investissez en marketing sans savoir clairement ce qui produit vraiment des résultats.","Vos équipes utilisent des outils d''IA, mais sans règles communes ni rôle défini.","Votre croissance (nouveaux marchés, produits ou publics) va plus vite que votre organisation."],"scale":["Pas du tout","Un peu","Souvent","Tout à fait"],"t":{"again":"Recommencer","answer":"Notre réponse","ctx":"Autodiagnostic — contrainte principale identifiée","low":"Aucune contrainte dominante ne ressort. C''est une bonne nouvelle — et un échange permettra de le confirmer.","note":"Une indication, pas un diagnostic : un vrai Diagnostic MCPS s''appuie sur vos données et des entretiens.","of":"sur","prev":"Précédent","profile":"Votre profil complet","q":"Affirmation","res_h":"Ce qui vous freine le plus probablement :","res_l":"Votre contrainte principale","see":"Voir l''offre","talk":"Parler de cette contrainte"}}', 'Sept affirmations, contrainte principale la plus marquée. Orientation, pas un diagnostic.', '2026-11-23T00:00:00Z');
INSERT OR IGNORE INTO questionnaire_versions (id, tool_id, version, content_hash, scoring_method, definition_json, validity_notes, published_at) VALUES ('coi@1.0', 'coi', '1.0', 'e33ed70cc7904aa1f995de4e4fcbdd08eada0fa55e72df90ebcf8cd53a9da768', 'coi-compute-v1', '{"questions":{"avoidable":{"id":"avoidable","l":{"en":"Share of that time spent on avoidable feedback and extra cycles","fr":"Part de ce temps consacrée aux retours évitables et cycles supplémentaires"},"n":14,"opts":[{"hi":10,"id":"lt10","l":{"en":"Under 10%","fr":"Moins de 10 %"},"lo":0},{"hi":25,"id":"10_25","l":{"en":"10 to 25%","fr":"10 à 25 %"},"lo":10},{"hi":50,"id":"26_50","l":{"en":"26 to 50%","fr":"26 à 50 %"},"lo":26},{"hi":75,"id":"51_75","l":{"en":"51 to 75%","fr":"51 à 75 %"},"lo":51},{"hi":100,"id":"gt75","l":{"en":"Over 75%","fr":"Plus de 75 %"},"lo":76},{"id":"unknown","l":{"en":"Impossible to estimate","fr":"Impossible à estimer"},"unknown":true}],"req":true,"type":"single"},"budget":{"d":{"en":"Include fees for agencies, studios, freelancers, concept, design, video, photography, motion design, post production, adaptations and versions. Exclude media buying and the salaries of internal teams.","fr":"Incluez les honoraires d''agences, studios, freelances, conception, design, vidéo, photographie, motion design, postproduction, déclinaisons et adaptations. Excluez l''achat média et les salaires des équipes internes."},"id":"budget","l":{"en":"Annual creative production budget (FCFA)","fr":"Budget annuel de production créative (FCFA)"},"max":10000000000000,"min":0,"n":4,"ph":{"en":"e.g. 40,000,000","fr":"ex. 40 000 000"},"req":true,"type":"money","warnAbove":100000000000},"challenges":{"id":"challenges","l":{"en":"Three main creative challenges (maximum three choices)","fr":"Trois principaux défis créatifs (maximum trois choix)"},"main":true,"max":3,"n":18,"opts":[{"id":"diff","l":{"en":"Campaigns lack differentiation","fr":"Manque de différenciation des campagnes"}},{"id":"consistency","l":{"en":"Lack of brand consistency","fr":"Manque de cohérence de marque"}},{"id":"lead","l":{"en":"Production lead times too long","fr":"Délais de production trop longs"}},{"id":"corrections","l":{"en":"Too many corrections","fr":"Multiplication des corrections"}},{"id":"vision","l":{"en":"No overall creative vision","fr":"Absence de vision créative globale"}},{"id":"agencies","l":{"en":"Difficulty managing agencies","fr":"Difficulté à piloter les agences"}},{"id":"coordination","l":{"en":"Lack of coordination","fr":"Manque de coordination"}},{"id":"measure","l":{"en":"Difficulty measuring creative performance","fr":"Difficulté à mesurer la performance créative"}},{"id":"dependence","l":{"en":"Dependence on suppliers","fr":"Dépendance aux prestataires"}},{"id":"concepts","l":{"en":"Difficulty turning strategy into concepts","fr":"Difficulté à transformer la stratégie en concepts"}},{"id":"resources","l":{"en":"Lack of specialist resources","fr":"Manque de ressources spécialisées"}}],"req":true,"type":"multi"},"changes":{"gov":"changes","id":"changes","l":{"en":"Frequency of changes after the brief or concept is approved","fr":"Fréquence des modifications après validation du brief ou du concept"},"n":11,"opts":[{"id":"never","l":{"en":"Never or exceptionally","fr":"Jamais ou exceptionnellement"},"rank":0},{"id":"rarely","l":{"en":"Rarely","fr":"Rarement"},"rank":1},{"id":"regular","l":{"en":"Regularly","fr":"Régulièrement"},"rank":2},{"id":"frequent","l":{"en":"Frequently","fr":"Fréquemment"},"rank":3},{"id":"very","l":{"en":"Very frequently","fr":"Très fréquemment"},"rank":4}],"req":true,"type":"single"},"cycles":{"gov":"cycles","id":"cycles","l":{"en":"Number of correction cycles","fr":"Nombre de cycles de correction"},"n":10,"opts":[{"id":"1","l":{"en":"1","fr":"1"},"rank":0},{"id":"2","l":{"en":"2","fr":"2"},"rank":1},{"id":"3","l":{"en":"3","fr":"3"},"rank":2},{"id":"4_5","l":{"en":"4 to 5","fr":"4 à 5"},"rank":3},{"id":"gt5","l":{"en":"More than 5","fr":"Plus de 5"},"rank":4},{"id":"none","l":{"en":"No standardised process","fr":"Aucun processus standardisé"},"rank":4}],"req":true,"type":"single"},"extra":{"d":{"en":"Several answers possible. This enriches the profile but is never added to the calculation, to avoid counting twice costs already covered by the share of rework.","fr":"Plusieurs réponses possibles. Cette information enrichit le profil mais n''est jamais ajoutée au calcul, pour éviter de compter deux fois des coûts déjà couverts par la part de reprises."},"exclusive":["none","unavailable"],"id":"extra","l":{"en":"External extra costs seen over the last 12 months","fr":"Surcoûts externes constatés au cours des 12 derniers mois"},"n":16,"opts":[{"id":"overtime","l":{"en":"Overtime billed","fr":"Heures supplémentaires facturées"}},{"id":"newprod","l":{"en":"New production services","fr":"Nouvelles prestations de production"}},{"id":"reshoot","l":{"en":"Video or photo reshoots","fr":"Reprises vidéo ou photographiques"}},{"id":"outofscope","l":{"en":"Adaptations outside the initial scope","fr":"Déclinaisons hors périmètre initial"}},{"id":"urgency","l":{"en":"Rush fees","fr":"Frais d''urgence"}},{"id":"reprint","l":{"en":"Reprinting or remanufacturing","fr":"Nouvelle impression ou fabrication"}},{"id":"none","l":{"en":"No extra cost identified","fr":"Aucun surcoût identifié"}},{"id":"unavailable","l":{"en":"Information not available","fr":"Information indisponible"}}],"profileOnly":true,"req":true,"type":"multi"},"factors":{"d":{"en":"Several answers possible.","fr":"Plusieurs réponses possibles."},"id":"factors","l":{"en":"Factors behind the rework","fr":"Facteurs à l''origine des reprises"},"main":true,"n":12,"opts":[{"id":"brief","l":{"en":"Incomplete initial brief","fr":"Brief initial incomplet"}},{"id":"objectives","l":{"en":"Marketing objectives not defined enough","fr":"Objectifs marketing insuffisamment définis"}},{"id":"stakeholders","l":{"en":"Too many stakeholders","fr":"Multiplication des interlocuteurs"}},{"id":"contradictory","l":{"en":"Contradictory feedback","fr":"Retours contradictoires"}},{"id":"direction","l":{"en":"Changes of direction","fr":"Changements de direction"}},{"id":"late","l":{"en":"Late involvement of management","fr":"Intervention tardive de la direction"}},{"id":"misunderstood","l":{"en":"Misunderstanding of the need","fr":"Mauvaise compréhension du besoin"}},{"id":"concept","l":{"en":"Disagreement on the concept","fr":"Désaccord sur le concept"}},{"id":"technical","l":{"en":"Technical constraints found late","fr":"Contraintes techniques découvertes tardivement"}},{"id":"regulatory","l":{"en":"Commercial or regulatory changes","fr":"Modifications commerciales ou réglementaires"}},{"id":"deadlines","l":{"en":"Deadlines too short","fr":"Délais trop courts"}},{"id":"noowner","l":{"en":"No final approval owner","fr":"Absence de responsable final de validation"}},{"id":"other","l":{"en":"Other","fr":"Autre"}}],"req":true,"type":"multi"},"horizon":{"id":"horizon","l":{"en":"Improvement horizon","fr":"Horizon d''amélioration"},"n":20,"opts":[{"id":"30d","l":{"en":"Immediately, within 30 days","fr":"Immédiatement, sous 30 jours"}},{"id":"3m","l":{"en":"Within the next 3 months","fr":"Dans les 3 prochains mois"}},{"id":"6m","l":{"en":"Within the next 6 months","fr":"Dans les 6 prochains mois"}},{"id":"12m","l":{"en":"Within the next 12 months","fr":"Dans les 12 prochains mois"}},{"id":"explore","l":{"en":"Exploring the current situation","fr":"Exploration de la situation actuelle"}}],"req":true,"type":"single"},"hourly":{"d":{"en":"Estimate of the loaded salary cost of the people involved, per hour of work. Use a weighted average if several profiles are involved.","fr":"Estimation du coût salarial chargé des collaborateurs concernés, rapporté à une heure de travail. Utilisez une moyenne pondérée si plusieurs profils interviennent."},"id":"hourly","l":{"en":"Average internal hourly cost (FCFA), optional","fr":"Coût horaire interne moyen (FCFA), facultatif"},"max":10000000,"min":0,"n":15,"ph":{"en":"e.g. 6,000","fr":"ex. 6 000"},"req":false,"type":"money","warnAbove":100000},"hours":{"d":{"en":"Add up the hours of everyone involved, on the marketing, communication, management and internal creative teams. Do not count the same hour twice.","fr":"Additionnez les heures de toutes les personnes concernées, côté marketing, communication, direction et équipes créatives internes. Ne comptez pas deux fois une même heure."},"id":"hours","l":{"en":"Total weekly hours spent on approvals, feedback, corrections and rework","fr":"Nombre total d''heures hebdomadaires consacrées aux validations, retours, corrections et reprises"},"max":10000,"min":0,"n":13,"ph":{"en":"e.g. 40","fr":"ex. 40"},"req":true,"type":"number","unit":{"en":"hours per week","fr":"heures par semaine"},"warnAbove":1000},"levels":{"gov":"levels","id":"levels","l":{"en":"Number of approval levels","fr":"Nombre de niveaux de validation"},"n":8,"opts":[{"id":"1","l":{"en":"1","fr":"1"},"rank":0},{"id":"2","l":{"en":"2","fr":"2"},"rank":1},{"id":"3","l":{"en":"3","fr":"3"},"rank":2},{"id":"4","l":{"en":"4","fr":"4"},"rank":3},{"id":"5p","l":{"en":"5 or more","fr":"5 ou plus"},"rank":4},{"id":"var","l":{"en":"Varies","fr":"Variable"},"rank":4}],"req":true,"type":"single"},"model":{"id":"model","l":{"en":"Creative production model","fr":"Modèle de production créative"},"n":3,"opts":[{"id":"internal","l":{"en":"In house team only","fr":"Équipe interne uniquement"}},{"id":"agency","l":{"en":"One external agency","fr":"Agence externe"}},{"id":"multi","l":{"en":"Several specialist agencies","fr":"Plusieurs agences spécialisées"}},{"id":"internal_agencies","l":{"en":"In house team + agencies","fr":"Équipe interne + agences"}},{"id":"freelance","l":{"en":"Freelancers and independents","fr":"Freelances et indépendants"}},{"id":"hybrid","l":{"en":"Hybrid model","fr":"Modèle hybride"}}],"req":true,"type":"single"},"outcome":{"id":"outcome","l":{"en":"Priority outcome sought","fr":"Résultat prioritaire recherché"},"n":19,"opts":[{"id":"costs","l":{"en":"Reduce unnecessary costs","fr":"Réduire les coûts inutiles"}},{"id":"speed","l":{"en":"Speed up approvals","fr":"Accélérer les validations"}},{"id":"quality","l":{"en":"Improve creative quality","fr":"Améliorer la qualité créative"}},{"id":"consistency","l":{"en":"Strengthen brand consistency","fr":"Renforcer la cohérence de marque"}},{"id":"performance","l":{"en":"Improve campaign performance","fr":"Améliorer la performance des campagnes"}},{"id":"governance","l":{"en":"Structure creative governance","fr":"Structurer la gouvernance créative"}},{"id":"agencies","l":{"en":"Improve agency management","fr":"Améliorer le pilotage des agences"}},{"id":"system","l":{"en":"Build a higher performing creative system","fr":"Construire un système créatif plus performant"}}],"req":true,"type":"single"},"people":{"gov":"people","id":"people","l":{"en":"Number of people involved in approving a major campaign","fr":"Nombre de personnes intervenant dans la validation d''une campagne importante"},"n":9,"opts":[{"id":"1_2","l":{"en":"1 to 2","fr":"1 à 2"},"rank":0},{"id":"3_4","l":{"en":"3 to 4","fr":"3 à 4"},"rank":1},{"id":"5_6","l":{"en":"5 to 6","fr":"5 à 6"},"rank":2},{"id":"7_10","l":{"en":"7 to 10","fr":"7 à 10"},"rank":3},{"id":"gt10","l":{"en":"More than 10","fr":"Plus de 10"},"rank":4}],"req":true,"type":"single"},"projects":{"id":"projects","l":{"en":"Number of campaigns or creative projects produced per year","fr":"Nombre de campagnes ou projets créatifs produits par an"},"n":5,"opts":[{"id":"lt10","l":{"en":"Fewer than 10","fr":"Moins de 10"}},{"id":"10_24","l":{"en":"10 to 24","fr":"10 à 24"}},{"id":"25_49","l":{"en":"25 to 49","fr":"25 à 49"}},{"id":"50_99","l":{"en":"50 to 99","fr":"50 à 99"}},{"id":"100_199","l":{"en":"100 to 199","fr":"100 à 199"}},{"id":"200p","l":{"en":"200 or more","fr":"200 et plus"}}],"req":true,"type":"single"},"rework":{"d":{"en":"Major rework means a change beyond simple retouching: a change of concept, a substantial rewrite, a redesigned visual, a new video version or the redoing of an already approved production.","fr":"Une reprise importante désigne une modification dépassant la simple retouche : changement de concept, réécriture substantielle, refonte d''un visuel, nouvelle version vidéo ou reprise d''une production déjà validée."},"id":"rework","l":{"en":"Share of projects needing major rework","fr":"Part des projets nécessitant des reprises importantes"},"n":7,"opts":[{"hi":10,"id":"lt10","l":{"en":"Under 10%","fr":"Moins de 10 %"},"lo":0},{"hi":25,"id":"10_25","l":{"en":"10 to 25%","fr":"10 à 25 %"},"lo":10},{"hi":50,"id":"26_50","l":{"en":"26 to 50%","fr":"26 à 50 %"},"lo":26},{"hi":75,"id":"51_75","l":{"en":"51 to 75%","fr":"51 à 75 %"},"lo":51},{"hi":100,"id":"gt75","l":{"en":"Over 75%","fr":"Plus de 75 %"},"lo":76},{"id":"unknown","l":{"en":"Hard to estimate","fr":"Difficile à estimer"},"unknown":true}],"req":true,"type":"single"},"sector":{"id":"sector","l":{"en":"Sector of activity","fr":"Secteur d''activité"},"n":1,"opts":[{"id":"bank","l":{"en":"Banking, finance and insurance","fr":"Banque, finance et assurance"}},{"id":"telco","l":{"en":"Telecommunications and technology","fr":"Télécommunications et technologies"}},{"id":"retail","l":{"en":"Retail and distribution","fr":"Grande distribution et commerce"}},{"id":"fmcg","l":{"en":"Food and FMCG","fr":"Agroalimentaire et FMCG"}},{"id":"auto","l":{"en":"Automotive and mobility","fr":"Automobile et mobilité"}},{"id":"realestate","l":{"en":"Real estate and construction","fr":"Immobilier et construction"}},{"id":"energy","l":{"en":"Energy, oil and mining","fr":"Énergie, pétrole et mines"}},{"id":"health","l":{"en":"Health and pharmaceuticals","fr":"Santé et industrie pharmaceutique"}},{"id":"transport","l":{"en":"Transport and logistics","fr":"Transport et logistique"}},{"id":"public","l":{"en":"Institutions and public sector","fr":"Institutions et secteur public"}},{"id":"media","l":{"en":"Media, culture and entertainment","fr":"Médias, culture et divertissement"}},{"id":"other","l":{"en":"Other","fr":"Autre"}}],"req":true,"type":"single"},"size":{"id":"size","l":{"en":"Size of the organisation","fr":"Taille de l''organisation"},"n":2,"opts":[{"id":"lt20","l":{"en":"Fewer than 20 employees","fr":"Moins de 20 collaborateurs"}},{"id":"20_49","l":{"en":"20 to 49 employees","fr":"20 à 49 collaborateurs"}},{"id":"50_99","l":{"en":"50 to 99 employees","fr":"50 à 99 collaborateurs"}},{"id":"100_249","l":{"en":"100 to 249 employees","fr":"100 à 249 collaborateurs"}},{"id":"250_499","l":{"en":"250 to 499 employees","fr":"250 à 499 collaborateurs"}},{"id":"500_999","l":{"en":"500 to 999 employees","fr":"500 à 999 collaborateurs"}},{"id":"1000p","l":{"en":"1,000 employees or more","fr":"1 000 collaborateurs et plus"}}],"req":true,"type":"single"},"types":{"d":{"en":"Several answers possible.","fr":"Plusieurs réponses possibles."},"id":"types","l":{"en":"Types of production","fr":"Types de productions"},"n":6,"opts":[{"id":"c360","l":{"en":"360 degree advertising campaigns","fr":"Campagnes publicitaires 360°"}},{"id":"branding","l":{"en":"Branding and identity","fr":"Branding et identité"}},{"id":"video","l":{"en":"Advertising and corporate videos","fr":"Vidéos publicitaires et institutionnelles"}},{"id":"motion","l":{"en":"Motion design","fr":"Motion design"}},{"id":"social","l":{"en":"Social media","fr":"Social media"}},{"id":"photo","l":{"en":"Photography and audiovisual","fr":"Photographie et audiovisuel"}},{"id":"plv","l":{"en":"Point of sale and outdoor","fr":"PLV et affichage"}},{"id":"events","l":{"en":"Activations and events","fr":"Activations et événementiel"}},{"id":"packaging","l":{"en":"Packaging","fr":"Packaging"}},{"id":"multiformat","l":{"en":"Multi format and multilingual adaptations","fr":"Déclinaisons multiformats et multilingues"}}],"req":true,"type":"multi"},"weeks":{"id":"weeks","init":"48","int":true,"l":{"en":"Number of weeks actually worked per year","fr":"Nombre de semaines effectivement travaillées par an"},"max":52,"min":1,"n":17,"ph":{"en":"48","fr":"48"},"req":true,"type":"number","unit":{"en":"weeks","fr":"semaines"}}},"steps":[{"i":{"en":"We would like to understand how your organisation designs, manages, approves and rolls out its creative output.","fr":"Nous souhaitons comprendre comment votre organisation conçoit, pilote, valide et déploie ses productions créatives."},"id":"context","q":["sector","size","model"],"t":{"en":"Organisation and context","fr":"Organisation et contexte"}},{"i":{"en":"A few markers of what your organisation invests in creative production and how much rework it involves.","fr":"Quelques repères sur ce que votre organisation investit dans la production créative et sur le volume de reprises."},"id":"invest","q":["budget","projects","types","rework"],"t":{"en":"Creative investment","fr":"Investissements créatifs"}},{"i":{"en":"How creative decisions are made, approved and corrected in your organisation.","fr":"Comment les décisions créatives sont prises, validées et corrigées dans votre organisation."},"id":"gov","q":["levels","people","cycles","changes","factors"],"t":{"en":"Governance and approvals","fr":"Gouvernance et validations"}},{"i":{"en":"The time and cost that approvals, feedback and corrections represent today.","fr":"Le temps et les coûts que représentent aujourd''hui les validations, retours et corrections."},"id":"costs","q":["hours","avoidable","hourly","extra","weeks"],"t":{"en":"Costs and operational resources","fr":"Coûts et ressources opérationnelles"}},{"i":{"en":"What you are trying to improve, and within what timeframe.","fr":"Ce que vous cherchez à améliorer, et dans quel délai."},"id":"strategy","q":["challenges","outcome","horizon"],"t":{"en":"Strategic priorities","fr":"Enjeux stratégiques"}}]}', 'Estimation indicative à partir de fourchettes déclarées ; jamais une économie garantie.', '2026-11-23T00:00:00Z');
INSERT OR IGNORE INTO questionnaire_versions (id, tool_id, version, content_hash, scoring_method, definition_json, validity_notes, published_at) VALUES ('maturity@1.0', 'maturity', '1.0', '981778599bbeafbb0ecdde1a11c485c24d5e0042daa092655483bff571fd1676', 'mat-score-v1', '{"dims":[{"d":{"en":"The ability to set a clear creative direction.","fr":"La capacité à définir une direction créative claire."},"id":"strategy","name":{"en":"Creative Strategy","fr":"Creative Strategy"},"q":["q1","q2","q3","q4"]},{"d":{"en":"Brand governance and consistency.","fr":"La gouvernance et la cohérence de la marque."},"id":"governance","name":{"en":"Brand Governance","fr":"Brand Governance"},"q":["q5","q6","q7","q8"]},{"d":{"en":"The quality of creative leadership.","fr":"La qualité du pilotage créatif."},"id":"leadership","name":{"en":"Creative Leadership","fr":"Creative Leadership"},"q":["q9","q10","q11","q12"]},{"d":{"en":"How creative work is organised.","fr":"L''organisation du travail créatif."},"id":"operating","name":{"en":"Creative Operating Model","fr":"Creative Operating Model"},"q":["q13","q14","q15","q16"]},{"d":{"en":"The ability to measure and improve creative performance.","fr":"La capacité à mesurer et améliorer la performance créative."},"id":"performance","name":{"en":"Creative Performance","fr":"Creative Performance"},"q":["q17","q18","q19","q20"]},{"d":{"en":"The ability to use technology and artificial intelligence.","fr":"La capacité à utiliser les technologies et l''intelligence artificielle."},"id":"technology","name":{"en":"AI & Technology Readiness","fr":"AI & Technology Readiness"},"q":["q21","q22","q23","q24"]}],"levels":[{"d":{"en":"Practices are mostly reactive and depend on individuals.","fr":"Les pratiques sont principalement réactives et dépendent des individus."},"max":36,"n":1,"name":{"en":"Initial","fr":"Initial"}},{"d":{"en":"Practices exist, but their application remains irregular.","fr":"Des pratiques existent, mais leur application reste irrégulière."},"max":52,"n":2,"name":{"en":"Emerging","fr":"Émergent"}},{"d":{"en":"The main processes and responsibilities are defined.","fr":"Les principaux processus et responsabilités sont définis."},"max":68,"n":3,"name":{"en":"Structured","fr":"Structuré"}},{"d":{"en":"Strategy, processes, teams and tools work together coherently.","fr":"La stratégie, les processus, les équipes et les outils fonctionnent de manière cohérente."},"max":84,"n":4,"name":{"en":"Integrated","fr":"Intégré"}},{"d":{"en":"The organisation has mechanisms for measurement, learning and continuous improvement.","fr":"L''organisation dispose de mécanismes de mesure, d''apprentissage et d''amélioration continue."},"max":101,"n":5,"name":{"en":"Optimised","fr":"Optimisé"}}],"minValid":3,"questions":{"q1":{"dim":"strategy","id":"q1","n":1,"s":{"en":"a formalised creative vision linked to objectives","fr":"une vision créative formalisée et reliée aux objectifs"},"t":{"en":"Does your organisation have a formalised creative vision linked to its commercial and marketing objectives?","fr":"Votre organisation dispose-t-elle d''une vision créative formalisée, reliée à ses objectifs commerciaux et marketing ?"}},"q10":{"dim":"leadership","id":"q10","n":10,"s":{"en":"creative decisions made by the appropriate people","fr":"des arbitrages créatifs réalisés par les personnes appropriées"},"t":{"en":"Are creative decisions made by people with the appropriate responsibilities and skills?","fr":"Les arbitrages créatifs sont-ils réalisés par des personnes disposant des responsabilités et compétences appropriées ?"}},"q11":{"dim":"leadership","id":"q11","n":11,"s":{"en":"common criteria to assess and challenge proposals","fr":"des critères communs pour évaluer et challenger les propositions"},"t":{"en":"Do teams have common criteria to assess and challenge creative proposals?","fr":"Les équipes disposent-elles de critères communs pour évaluer et challenger les propositions créatives ?"}},"q12":{"dim":"leadership","id":"q12","n":12,"s":{"en":"early involvement of management in projects","fr":"une intervention de la direction suffisamment tôt dans les projets"},"t":{"en":"Does management step in early enough to steer projects rather than changing productions already under way?","fr":"La direction intervient-elle suffisamment tôt pour orienter les projets plutôt que modifier tardivement des productions déjà engagées ?"}},"q13":{"dim":"operating","id":"q13","n":13,"s":{"en":"formalised, understood production and approval processes","fr":"des processus de production et de validation formalisés et compris"},"t":{"en":"Are production and approval processes formalised and understood by stakeholders?","fr":"Les processus de production et de validation sont-ils formalisés et compris par les parties prenantes ?"}},"q14":{"dim":"operating","id":"q14","n":14,"s":{"en":"clearly defined roles between internal teams, agencies and suppliers","fr":"des rôles clairement définis entre équipes internes, agences et prestataires"},"t":{"en":"Are roles between internal teams, agencies and suppliers clearly defined?","fr":"Les rôles entre équipes internes, agences et prestataires sont-ils clairement définis ?"}},"q15":{"dim":"operating","id":"q15","n":15,"s":{"en":"approval of briefs before production starts","fr":"la validation des briefs avant le démarrage des productions"},"t":{"en":"Are briefs approved before production starts?","fr":"Les briefs sont-ils validés avant le démarrage des productions ?"}},"q16":{"dim":"operating","id":"q16","n":16,"s":{"en":"mechanisms to handle contradictory feedback and changing priorities","fr":"des mécanismes pour traiter les retours contradictoires et les changements de priorité"},"t":{"en":"Does the organisation have mechanisms to handle contradictory feedback and changing priorities?","fr":"L''organisation dispose-t-elle de mécanismes permettant de traiter les retours contradictoires et les changements de priorité ?"}},"q17":{"dim":"performance","id":"q17","n":17,"s":{"en":"indicators of the contribution of creative activities to marketing objectives","fr":"des indicateurs de contribution des activités créatives aux objectifs marketing"},"t":{"en":"Do indicators make it possible to assess the contribution of creative activities to marketing objectives?","fr":"Des indicateurs permettent-ils d''évaluer la contribution des activités créatives aux objectifs marketing ?"}},"q18":{"dim":"performance","id":"q18","n":18,"s":{"en":"analysis of campaign performance after release","fr":"l''analyse des performances des campagnes après diffusion"},"t":{"en":"Is campaign performance analysed after release?","fr":"Les performances des campagnes sont-elles analysées après leur diffusion ?"}},"q19":{"dim":"performance","id":"q19","n":19,"s":{"en":"reuse of lessons from previous campaigns","fr":"la réutilisation des enseignements des campagnes précédentes"},"t":{"en":"Are the lessons of previous campaigns reused in later briefs and decisions?","fr":"Les enseignements des campagnes précédentes sont-ils réutilisés dans les briefs et les décisions suivantes ?"}},"q2":{"dim":"strategy","id":"q2","n":2,"s":{"en":"a shared understanding of positioning and creative territory","fr":"une compréhension commune du positionnement et du territoire créatif"},"t":{"en":"Do the teams share a common understanding of the brand''s positioning and creative territory?","fr":"Les équipes disposent-elles d''une compréhension commune du positionnement et du territoire créatif de la marque ?"}},"q20":{"dim":"performance","id":"q20","n":20,"s":{"en":"the distinction between production quality, operational efficiency and marketing results","fr":"la distinction entre qualité de production, efficacité opérationnelle et résultats marketing"},"t":{"en":"Does the organisation distinguish production quality, operational efficiency and marketing results?","fr":"L''organisation distingue-t-elle la qualité de production, l''efficacité opérationnelle et les résultats marketing ?"}},"q21":{"dim":"technology","id":"q21","n":21,"s":{"en":"identification of tasks that could benefit from automation","fr":"l''identification des tâches pouvant bénéficier de l''automatisation"},"t":{"en":"Has your organisation identified the creative or operational tasks that could benefit from automation?","fr":"Votre organisation a-t-elle identifié les tâches créatives ou opérationnelles pouvant bénéficier de l''automatisation ?"}},"q22":{"dim":"technology","id":"q22","n":22,"s":{"en":"tools suited to collaboration, asset sharing and tracking","fr":"des outils adaptés à la collaboration, au partage des actifs et au suivi"},"t":{"en":"Do teams have tools suited to collaboration, asset sharing and production tracking?","fr":"Les équipes disposent-elles d''outils adaptés à la collaboration, au partage des actifs et au suivi des productions ?"}},"q23":{"dim":"technology","id":"q23","n":23,"s":{"en":"rules governing the use of artificial intelligence","fr":"des règles encadrant l''usage de l''intelligence artificielle"},"t":{"en":"Are there rules governing the use of artificial intelligence in creative activities?","fr":"Existe-t-il des règles encadrant l''utilisation de l''intelligence artificielle dans les activités créatives ?"}},"q24":{"dim":"technology","id":"q24","n":24,"s":{"en":"regular assessment of the relevance of tools and technologies","fr":"l''évaluation régulière de la pertinence des outils et technologies"},"t":{"en":"Does the organisation regularly assess the relevance of its creative tools and technologies?","fr":"L''organisation évalue-t-elle régulièrement la pertinence de ses outils et technologies créatives ?"}},"q3":{"dim":"strategy","id":"q3","n":3,"s":{"en":"the translation of marketing objectives into creative directions in briefs","fr":"la traduction des objectifs marketing en orientations créatives dans les briefs"},"t":{"en":"Do creative briefs systematically translate marketing objectives into precise creative directions?","fr":"Les briefs créatifs traduisent-ils systématiquement les objectifs marketing en orientations créatives précises ?"}},"q4":{"dim":"strategy","id":"q4","n":4,"s":{"en":"defined strategic criteria for assessing creative decisions","fr":"des critères stratégiques définis pour évaluer les décisions créatives"},"t":{"en":"Are creative decisions assessed against defined strategic criteria rather than decision makers'' personal preferences?","fr":"Les décisions créatives sont-elles évaluées selon des critères stratégiques définis plutôt que selon les préférences personnelles des décideurs ?"}},"q5":{"dim":"governance","id":"q5","n":5,"s":{"en":"clearly assigned brand governance responsibilities","fr":"des responsabilités de gouvernance de marque clairement attribuées"},"t":{"en":"Are responsibilities for brand governance clearly assigned?","fr":"Les responsabilités liées à la gouvernance de la marque sont-elles clairement attribuées ?"}},"q6":{"dim":"governance","id":"q6","n":6,"s":{"en":"documented rules on the use and evolution of the brand identity","fr":"des règles documentées sur l''usage et l''évolution de l''identité de marque"},"t":{"en":"Are there documented rules governing the use and evolution of the brand identity?","fr":"Existe-t-il des règles documentées encadrant l''utilisation et l''évolution de l''identité de marque ?"}},"q7":{"dim":"governance","id":"q7","n":7,"s":{"en":"an accessible, up to date brand reference","fr":"un référentiel de marque accessible et actualisé"},"t":{"en":"Do internal teams and agencies have an accessible, up to date brand reference?","fr":"Les équipes internes et les agences disposent-elles d''un référentiel de marque accessible et actualisé ?"}},"q8":{"dim":"governance","id":"q8","n":8,"s":{"en":"control of local, commercial or event adaptations","fr":"le contrôle des adaptations locales, commerciales ou événementielles"},"t":{"en":"Are local, commercial or event adaptations controlled to preserve overall brand consistency?","fr":"Les adaptations locales, commerciales ou événementielles sont-elles contrôlées pour préserver la cohérence globale de la marque ?"}},"q9":{"dim":"leadership","id":"q9","n":9,"s":{"en":"clear responsibility for overall creative direction","fr":"une responsabilité claire de la direction créative globale"},"t":{"en":"Does a person or function hold responsibility for overall creative direction?","fr":"Une personne ou une fonction possède-t-elle la responsabilité de la direction créative globale ?"}}},"scale":[{"d":{"en":"No identifiable practice.","fr":"Aucune pratique identifiable."},"name":{"en":"Absent","fr":"Absent"},"v":1},{"d":{"en":"Occasional practice, not documented.","fr":"Pratique ponctuelle, non documentée."},"name":{"en":"Informal","fr":"Informel"},"v":2},{"d":{"en":"Practices exist but are irregular.","fr":"Pratiques existantes mais irrégulières."},"name":{"en":"Developing","fr":"En développement"},"v":3},{"d":{"en":"Practices are formalised and regularly applied.","fr":"Pratiques formalisées et régulièrement appliquées."},"name":{"en":"Structured","fr":"Structuré"},"v":4},{"d":{"en":"Practices are mastered, measured and continuously improved.","fr":"Pratiques maîtrisées, mesurées et continuellement améliorées."},"name":{"en":"Integrated","fr":"Intégré"},"v":5}]}', 'Instrument propriétaire d''autoévaluation, pas une certification indépendante.', '2026-11-23T00:00:00Z');
INSERT OR IGNORE INTO questionnaire_versions (id, tool_id, version, content_hash, scoring_method, definition_json, validity_notes, published_at) VALUES ('brand@1.0', 'brand', '1.0', 'b6a09899d34919b2379ad261964547465885c8e69a5bd3e8030c22621d7a2c78', 'brand-evidence-v1', '{"cats":[{"id":"A","kinds":[["logo","Logo","Logo"],["guidelines","Brand guidelines","Brand guidelines"],["charter","Charte graphique","Graphic charter"]],"name":{"en":"Brand identity","fr":"Identité de marque"}},{"id":"B","kinds":[["campaign","Campagne publicitaire","Advertising campaign"],["social","Publication social media","Social media post"],["promo","Visuel promotionnel","Promotional visual"],["video","Vidéo ou capture représentative","Video or representative capture"]],"name":{"en":"Communication","fr":"Communication"}},{"id":"C","kinds":[["site","Site web","Website"],["socialpage","Page sociale","Social page"],["sales","Support commercial","Sales material"]],"name":{"en":"Digital presence","fr":"Présence digitale"}},{"id":"D","kinds":[["identity","Identité","Identity"],["campaign","Campagne","Campaign"],["public","Support public","Public material"]],"name":{"en":"Competitive references","fr":"Références concurrentielles"}}],"dims":[{"c":[{"dim":"visual","id":"visual.colors","l":{"en":"Colour consistency","fr":"Cohérence des couleurs"}},{"dim":"visual","id":"visual.type","l":{"en":"Typographic consistency","fr":"Cohérence typographique"}},{"dim":"visual","id":"visual.logo","l":{"en":"Use of the logo","fr":"Usage du logo"}},{"dim":"visual","id":"visual.graphics","l":{"en":"Consistency of graphic elements","fr":"Cohérence des éléments graphiques"}},{"dim":"visual","id":"visual.rules","l":{"en":"Compliance with visual rules","fr":"Respect des règles visuelles"}},{"dim":"visual","id":"visual.variations","l":{"en":"Unjustified variations","fr":"Variations non justifiées"}}],"d":{"en":"The consistency of the visual identity from one material to the next.","fr":"La cohérence de l''identité visuelle d''un support à l''autre."},"id":"visual","name":{"en":"Visual Identity Consistency","fr":"Visual Identity Consistency"},"risk":{"en":"visual variations can weaken the legibility and recognition of the brand","fr":"des variations visuelles peuvent affaiblir la lisibilité et la reconnaissance de la marque"},"stem":{"en":"Harmonise","fr":"Harmoniser"}},{"c":[{"dim":"verbal","id":"verbal.tone","l":{"en":"Tone of communication","fr":"Ton de communication"}},{"dim":"verbal","id":"verbal.vocab","l":{"en":"Vocabulary","fr":"Vocabulaire"}},{"dim":"verbal","id":"verbal.messages","l":{"en":"Key messages","fr":"Messages clés"}},{"dim":"verbal","id":"verbal.promise","l":{"en":"Brand promise","fr":"Promesse de marque"}},{"dim":"verbal","id":"verbal.voices","l":{"en":"Consistency of statements","fr":"Cohérence des prises de parole"}},{"dim":"verbal","id":"verbal.continuity","l":{"en":"Continuity of discourse","fr":"Continuité du discours"}}],"d":{"en":"The consistency of tone and discourse from one statement to the next.","fr":"La cohérence du ton et du discours d''une prise de parole à l''autre."},"id":"verbal","name":{"en":"Verbal Identity Consistency","fr":"Verbal Identity Consistency"},"risk":{"en":"a discourse that varies can blur what the brand says about itself","fr":"un discours qui varie peut brouiller ce que la marque dit d''elle-même"},"stem":{"en":"Align","fr":"Aligner"}},{"c":[{"dim":"positioning","id":"positioning.match","l":{"en":"Match between declared positioning and actual expression","fr":"Correspondance entre positionnement déclaré et expression réelle"}},{"dim":"positioning","id":"positioning.value","l":{"en":"Clarity of the value proposition","fr":"Clarté de la proposition de valeur"}},{"dim":"positioning","id":"positioning.commercial","l":{"en":"Consistency of commercial messages","fr":"Cohérence des messages commerciaux"}},{"dim":"positioning","id":"positioning.discourse","l":{"en":"Consistency between discourse and materials","fr":"Cohérence entre discours et supports"}}],"d":{"en":"The alignment between declared positioning and actual expression.","fr":"L''alignement entre le positionnement déclaré et l''expression réelle."},"id":"positioning","name":{"en":"Brand Positioning Alignment","fr":"Brand Positioning Alignment"},"risk":{"en":"a gap between positioning and expression can make the value proposition less legible","fr":"un écart entre positionnement et expression peut rendre la proposition de valeur moins lisible"},"stem":{"en":"Clarify","fr":"Clarifier"}},{"c":[{"dim":"distinct","id":"distinct.codes","l":{"en":"Uniqueness of visual codes","fr":"Singularité des codes visuels"}},{"dim":"distinct","id":"distinct.territories","l":{"en":"Originality of creative territories","fr":"Originalité des territoires créatifs"}},{"dim":"distinct","id":"distinct.diff","l":{"en":"Apparent differentiation","fr":"Différenciation apparente"}},{"dim":"distinct","id":"distinct.conventions","l":{"en":"Repetition of sector conventions","fr":"Répétition des conventions sectorielles"}},{"dim":"distinct","id":"distinct.elements","l":{"en":"Consistency of distinctive elements","fr":"Cohérence des éléments distinctifs"}}],"d":{"en":"The observable distinctive elements, compared with competitive references. It does not measure recognition among audiences.","fr":"Les éléments distinctifs observables, par comparaison avec les références concurrentielles. Elle ne mesure pas la reconnaissance auprès des audiences."},"id":"distinct","name":{"en":"Creative Distinctiveness","fr":"Creative Distinctiveness"},"needsCompetitor":true,"risk":{"en":"codes close to those of the sector can make the brand less distinctive on observation","fr":"des codes proches de ceux du secteur peuvent rendre la marque moins distinctive à l''observation"},"stem":{"en":"Strengthen","fr":"Renforcer"}},{"c":[{"dim":"cross","id":"cross.websocial","l":{"en":"Consistency between website and social media","fr":"Cohérence entre site web et réseaux sociaux"}},{"dim":"cross","id":"cross.adsales","l":{"en":"Consistency between advertising and sales materials","fr":"Cohérence entre publicité et supports commerciaux"}},{"dim":"cross","id":"cross.instpromo","l":{"en":"Consistency between institutional and promotional communication","fr":"Cohérence entre communication institutionnelle et promotionnelle"}},{"dim":"cross","id":"cross.formats","l":{"en":"Adaptation to formats","fr":"Adaptation aux formats"}},{"dim":"cross","id":"cross.territory","l":{"en":"Continuity of the brand territory","fr":"Continuité du territoire de marque"}}],"d":{"en":"The consistency of expression from one channel to another.","fr":"La cohérence de l''expression d''un canal à l''autre."},"id":"cross","name":{"en":"Cross-Channel Consistency","fr":"Cross-Channel Consistency"},"risk":{"en":"expression that changes from one channel to another can fragment the brand experience","fr":"une expression qui change d''un canal à l''autre peut fragmenter l''expérience de la marque"},"stem":{"en":"Unify","fr":"Unifier"}},{"c":[{"dim":"governance","id":"governance.rules","l":{"en":"Existence of brand rules","fr":"Existence des règles de marque"}},{"dim":"governance","id":"governance.access","l":{"en":"Accessibility of guidelines","fr":"Accessibilité des guidelines"}},{"dim":"governance","id":"governance.adapt","l":{"en":"Consistency of adaptations","fr":"Cohérence des adaptations"}},{"dim":"governance","id":"governance.external","l":{"en":"Control of external productions","fr":"Contrôle des productions externes"}},{"dim":"governance","id":"governance.standards","l":{"en":"Compliance with standards","fr":"Respect des standards"}},{"dim":"governance","id":"governance.validation","l":{"en":"Validation mechanisms","fr":"Mécanismes de validation"}}],"d":{"en":"The existence and application of brand rules.","fr":"L''existence et l''application des règles de marque."},"id":"governance","name":{"en":"Brand Governance & Application","fr":"Brand Governance & Application"},"risk":{"en":"absent or poorly applied rules can let gaps settle in from one production to the next","fr":"des règles absentes ou peu appliquées peuvent laisser les écarts s''installer d''une production à l''autre"},"stem":{"en":"Formalise","fr":"Formaliser"}}],"limits":{"formats":["pdf","png","jpg","jpeg","webp"],"maxFileBytes":10485760,"maxSupports":25,"maxText":600,"mime":["application/pdf","image/png","image/jpeg","image/webp"],"minFact":10},"profile":[{"id":"name","l":{"en":"Brand name","fr":"Nom de la marque"},"req":true,"type":"text"},{"id":"sector","l":{"en":"Sector of activity","fr":"Secteur d''activité"},"req":true,"type":"select"},{"id":"market","l":{"en":"Geographic market","fr":"Marché géographique"},"req":true,"type":"text"},{"id":"audience","l":{"en":"Main target audience","fr":"Public cible principal"},"req":true,"type":"text"},{"id":"positioning","l":{"en":"Declared positioning","fr":"Positionnement déclaré"},"req":true,"type":"textarea"},{"id":"competitors","l":{"en":"Main competitors","fr":"Principaux concurrents"},"req":false,"type":"textarea"},{"id":"channels","l":{"en":"Main communication channels","fr":"Principaux canaux de communication"},"req":true,"type":"multi"}],"rules":{"minDistinctSupports":2,"minObserved":3,"minShareOfApplicable":0.5},"status":[{"id":"conform","name":{"en":"Compliant","fr":"Conforme"},"observed":true,"w":1},{"id":"partial","name":{"en":"Partially compliant","fr":"Partiellement conforme"},"observed":true,"w":0.5},{"id":"non","name":{"en":"Non compliant","fr":"Non conforme"},"observed":true,"w":0},{"id":"unobservable","name":{"en":"Not observable","fr":"Non observable"},"observed":false},{"id":"na","name":{"en":"Not applicable","fr":"Non applicable"},"observed":false}]}', 'Revue guidée : aucun fichier lu ni analysé automatiquement ; constats déclarés par l''utilisateur.', '2026-11-23T00:00:00Z');

INSERT OR IGNORE INTO consent_texts (id, tool_id, purpose, lang, body, body_hash, published_at) VALUES ('tx-coi-fr-v1', 'coi', 'transmission', 'fr', 'J''accepte que MAIORIS reçoive mes réponses et mon Snapshot, les conserve 12 mois et les utilise pour me répondre. Politique de confidentialité.', '77f57f66091afec7569b4567abead79b4bd7b96fe47a309d3bfd75e5b9708898', '2026-11-23T00:00:00Z');
